\label{def:transverse}
A family $U = (U_1,\dots,U_d)$ of open subsets of $\mathbb{R}^d$ is transverse if, for some $c\in(0,1)$,
\begin{equation}
    \Psi_U(x) \stackrel{\mathrm{def}}{=} 1+\sum_{j=1}^d\mathsf{d}(x,\partial U_j) \ \ge\ |x|^c, \qquad |x| \ge c^{-1}.
\end{equation}

\label{def:X}
Fix a radial, nonnegative $\eta \in C_0^\infty\big(B(0,1)\big)$ with $\int_{\mathbb{R}^d} \eta = 1$, and set
\begin{equation}
    f_j \stackrel{\mathrm{def}}{=} \1_{U_j}*\eta, \qquad F_U \stackrel{\mathrm{def}}{=} (f_1,\dots,f_d) : \mathbb{R}^d\to[0,1]^d, \qquad J_U \stackrel{\mathrm{def}}{=} \det(\nabla f_1,\dots,\nabla f_d).
\end{equation}
The intersection number of $U$ is
\begin{equation}\label{eq:X}
    \mathcal{X}_U \stackrel{\mathrm{def}}{=} \int_{\mathbb{R}^d}J_U(x)\,dx.
\end{equation}

\label{thm:main}
If $U$ is a transverse family of subsets of $\mathbb{R}^d$, then
\begin{equation}\label{eq:main}
    c_U(P) = \mathcal{X}_U\cdot c_H(P).
\end{equation}

\label{def:cochain}
A $k$-cochain is a function $\varphi : (\mathbb{Z}^d)^{k+1}\to\mathbb{C}$. We say that:
\begin{enumerate}[label=(\alph*)]
    \item $\varphi$ is alternating if
    \begin{equation}
        \varphi(x_{\pi(0)},\dots,x_{\pi(k)}) = \operatorname{sgn}(\pi)\,\varphi(x_0,\dots,x_k), \qquad \pi\in S_{k+1}.
    \end{equation}
    \item $\varphi$ is controlled if, for some $C,M\ge1$,
    \begin{equation}\label{eq:controlled}
        |\varphi(\mathbf{x})|\le C\left\langle \operatorname{diam} \mathbf{x} \right\rangle^M\left\langle x_0 \right\rangle^{-d-1}, \qquad \operatorname{diam} \mathbf{x} \stackrel{\mathrm{def}}{=} \max_{i,j}|x_i-x_j|.
    \end{equation}
\end{enumerate}

\label{lem:convergence}
For every $N$ there is $C_N$ such that
\begin{equation}\label{eq:Pi-decay}
    |\Pi_P(\mathbf{x})| \le C_N\left\langle \operatorname{diam} \mathbf{x} \right\rangle^{-N}\prod_{i=0}^{k-1}\left\langle x_{i+1}-x_i \right\rangle^{-N}.
\end{equation}
In particular, if $\varphi$ is controlled, the series \eqref{eq:tauP} defining $\tau_P(\varphi)$ converges absolutely.

With $x_{k+1}\stackrel{\mathrm{def}}{=} x_0$, the decay \eqref{eq:P-decay} gives $|P(x_i,x_{i+1})|\le C_{2N}\left\langle x_{i+1}-x_i \right\rangle^{-2N}$ for each of the $k+1$ factors. Half the powers produce the product from $i=0$ to $k-1$ in \eqref{eq:Pi-decay}. The other half produce
\begin{equation}
    \prod_{i=0}^k\left\langle x_{i+1}-x_i \right\rangle^{-N} \le c_k^{-N} \left\langle \operatorname{diam} \mathbf{x} \right\rangle^{-N}.
\end{equation}    
Indeed, we have     
\begin{equation}
    \prod_{i=0}^k\left\langle x_{i+1}-x_i \right\rangle\ \ge\ c_k\left\langle \operatorname{diam} \mathbf{x} \right\rangle,
\end{equation}
which holds because the closed path $x_0\to x_1\to\dots\to x_k\to x_0$ has length at least $\operatorname{diam} \mathbf{x}$. This proves \eqref{eq:Pi-decay}.

Now let $\varphi$ be controlled. By \eqref{eq:controlled} and \eqref{eq:Pi-decay} with $N = M+d+1$,
\begin{equation}
    |\varphi(\mathbf{x}) \cdot \Pi_P(\mathbf{x})| \le C\left\langle x_0 \right\rangle^{-d-1}\prod_{i=0}^{k-1}\left\langle x_{i+1}-x_i \right\rangle^{-d-1}.
\end{equation}
Summing over $x_k$, then $x_{k-1}$, \dots, then $x_0$, we obtain:
\begin{equation}\label{eq:sum-bound}
    \sum_{\mathbf{x}\in(\mathbb{Z}^d)^{k+1}}|\varphi(\mathbf{x}) \cdot \Pi_P(\mathbf{x})| \le C\sum_{x_0\in\mathbb{Z}^d}\left\langle x_0 \right\rangle^{-d-1}\Big(\sum_{y\in\mathbb{Z}^d}\left\langle y \right\rangle^{-d-1}\Big)^k < \infty.
\end{equation}
This completes the proof.

\label{lem:cochain}
Let $U$ be transverse and
\begin{equation}
    G_U \stackrel{\mathrm{def}}{=} (\1_{U_1},\dots,\1_{U_d}) : \mathbb{Z}^d\to\{0,1\}^d.
\end{equation}
Then $c_U(P) = \tau_P(\varphi_U)$, where $\varphi_U$ is the alternating and controlled $d$-cochain
\begin{equation}\label{eq:phiU}
    \varphi_U(x_0,\dots,x_d) \stackrel{\mathrm{def}}{=} \frac{1}{d!}\det\big[G_U(x_1)-G_U(x_0),\dots,G_U(x_d)-G_U(x_0)\big].
\end{equation}

The kernel of $[P,\1_{U_j}]$ is
\begin{equation}
    [P,\1_{U_j}](x,y) = P(x,y)\big(\1_{U_j}(y)-\1_{U_j}(x)\big).
\end{equation}
We label the summation variables so that the $k$-th commutator joins $x_{k-1}$ to $x_k$, and the first factor $P$ joins $x_d$ to $x_0$. By cyclicity of $\operatorname{tr}$, we get
\begin{equation}\label{eq:trace-expansion}
    \operatorname{Tr}\big(P[P,\1_{U_1}]\cdots[P,\1_{U_d}]\big) = \sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}}\Pi_P(\mathbf{x}) \cdot \prod_{k=1}^d\big(\1_{U_k}(x_k)-\1_{U_k}(x_{k-1})\big).
\end{equation}
This sum converges absolutely by \Cref{lem:convergence}, because the product
\begin{equation}\label{eq:AU}
    A_U(\mathbf{x}) \stackrel{\mathrm{def}}{=} \prod_{k=1}^d\big(\1_{U_k}(x_k)-\1_{U_k}(x_{k-1})\big)
\end{equation}
emerging above defines a controlled $d$-cochain. Indeed, for $A_U(\mathbf{x})$ to be non-zero, one of the points $x_{k-1}, x_k$ needs to be in $U_k$, and the other in $U_k^c$. Hence
\begin{equation}
    \mathsf{d}(x_0,\partial U_k) \leq \max\big(|x_0-x_k|, |x_0 - x_{k-1}|\big) \leq \operatorname{diam} \mathbf{x}.
\end{equation}
Summing over $k$, and using transversality, we obtain that if $A_U(\mathbf{x}) \neq 0$ and $|x_0| \geq c^{-1}$,
\begin{equation}
    |x_0|^c \leq \Psi_U(x_0)\le 1+d\operatorname{diam} \mathbf{x}.
\end{equation}
In particular, using that all factors in \eqref{eq:AU} are in $\{-1,0,1\}$, if $A_U(\mathbf{x})\neq 0$ and $|x_0| \geq c^{-1}$,
\begin{equation}\label{eq:AU-bound}
    |A_U(\mathbf{x})| \leq 1 \leq \big((1+d\operatorname{diam} \mathbf{x}) |x_0|^{-c}\big)^{\tfrac{d+1}{c}} \leq C \left\langle \operatorname{diam} \mathbf{x} \right\rangle^{\tfrac{d+1}{c}} \left\langle x_0 \right\rangle^{-d-1}.
\end{equation}
Since $c\in(0,1)$, the exponent $\frac{d+1}{c}$ is larger than $1$, as required in \Cref{def:cochain}. We note that if $A_U(\mathbf{x}) = 0$ or $|x_0| \leq c^{-1}$, then \eqref{eq:AU-bound} holds trivially (after potentially increasing $C$). Therefore $A_U$ is controlled.


Antisymmetrizing \eqref{eq:trace-expansion}, we obtain
\begin{equation}
\begin{aligned}
    c_U(P) &= \operatorname{Tr}\big(P\,[P,\1_{U_1}]\wedge\cdots\wedge[P,\1_{U_d}]\big) 
    \\
    &= \sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}} \varphi_U(\mathbf{x}) \cdot \Pi_P(\mathbf{x}) = \tau_P(\varphi_U), 
 \end{aligned}
\end{equation}
where $\varphi_U$ is the $d$-cochain defined by
\begin{equation}
    \varphi_U(\mathbf{x}) \stackrel{\mathrm{def}}{=} \frac{1}{d!}\det[v_1,\dots,v_d], \qquad v_k \stackrel{\mathrm{def}}{=} G_U(x_k)-G_U(x_{k-1}).
\end{equation}
Replacing each $v_k$ by $v_1+\dots+v_k = G_U(x_k)-G_U(x_0)$ does not change the above determinant, and confirms the identity \eqref{eq:phiU}. This identity immediately justifies that the cochain $\varphi_U$ is alternating. Moreover, it is a linear combination of $d!$ (controlled) cochains of the form \eqref{eq:AU} over permutations of $U = (U_1, \dots, U_d)$. So $\varphi_U$ is also controlled. This completes the proof.

By definition,
\begin{equation}
    \tau_P(\delta\psi) = \sum_{i=0}^d(-1)^i\sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}}\psi(x_0,\dots,\widehat{x_i},\dots,x_d) \cdot \Pi_P(\mathbf{x}).
\end{equation}
The infinite sum above is absolutely convergent. Indeed, set $N = M+d+1$. If $i \geq 1$, we have:
\begin{align}
    \sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}}\big|\psi(x_0,\dots,\widehat{x_i},\dots,x_d) \cdot \Pi_P(\mathbf{x})\big| &\leq C\sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}} \left\langle x_0 \right\rangle^{-d-1} \left\langle \operatorname{diam} \mathbf{x} \right\rangle^{M-N} \prod_{j=0}^{d-1}\left\langle x_{j+1}-x_j \right\rangle^{-N} \notag\\
    &\leq C\sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}} \left\langle x_0 \right\rangle^{-d-1} \prod_{j=0}^{d-1}\left\langle x_{j+1}-x_j \right\rangle^{-N}, \label{eq:face-i}
\end{align}
and if $i=0$, then by \eqref{eq:peetre}:
\begin{align}
    \sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}}\big|\psi(\widehat{x_0},x_1,\dots,x_d) \cdot \Pi_P(\mathbf{x})\big| &\leq C\sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}} \left\langle x_1 \right\rangle^{-d-1} \left\langle \operatorname{diam} \mathbf{x} \right\rangle^{M-N} \prod_{j=0}^{d-1}\left\langle x_{j+1}-x_j \right\rangle^{-N} \notag\\
    &\leq C\sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}} \left\langle x_0 \right\rangle^{-d-1} \left\langle \operatorname{diam} \mathbf{x} \right\rangle^{M+d+1-N} \prod_{j=0}^{d-1}\left\langle x_{j+1}-x_j \right\rangle^{-N} \notag\\
    &\leq C\sum_{\mathbf{x}\in(\mathbb{Z}^d)^{d+1}} \left\langle x_0 \right\rangle^{-d-1} \prod_{j=0}^{d-1}\left\langle x_{j+1}-x_j \right\rangle^{-N}. \label{eq:face-0}
\end{align}
The right-hand sides of \eqref{eq:face-i} and \eqref{eq:face-0} converge as in \eqref{eq:sum-bound}.

In the $i$-th term, we sum over $x_i$ first. Since $P^2=P$,
\begin{equation}
    \sum_{x_i\in\mathbb{Z}^d}P(x_{i-1},x_i)P(x_i,x_{i+1}) = P(x_{i-1},x_{i+1}) \qquad (\text{indices mod } d+1),
\end{equation}
so the $i$-th term equals $(-1)^i\tau_P(\psi)$, and, since $d$ is even, $\tau_P(\delta\psi) = \tau_P(\psi)$. The permutation
\begin{equation}
    (y_0,\dots,y_{d-1})\mapsto(y_1,\dots,y_{d-1},y_0)
\end{equation}
leaves $\Pi_P$ invariant and flips the sign of $\psi$, because a $d$-cycle has signature $(-1)^{d+1} = -1$. Hence $\tau_P(\psi) = 0$, and this completes the proof.

\label{lem:prism}
Let $F:\mathbb{R}^d\to\mathbb{R}^d$ be smooth and $G:\mathbb{Z}^d\to\mathbb{R}^d$ be any map. Then there exists an alternating $(d-1)$-cochain $q$ such that
\begin{equation}\label{eq:prism}
    \mathbf{G}^*I[\omega] = I[F^*\omega]+\delta q, \qquad \mathbf{G}(\mathbf{x}) \stackrel{\mathrm{def}}{=} \big(G(x_0),\dots,G(x_d)\big).
\end{equation}

As for $\mathbf{G}_U$, we use the notation
\begin{equation}
    \mathbf{G}(\mathbf{y})\stackrel{\mathrm{def}}{=}\big(G(y_0),\dots,G(y_k)\big), \qquad \big(\mathbf{G}^*I[\omega]\big)(\mathbf{x})\stackrel{\mathrm{def}}{=} I[\omega]\big(\mathbf{G}(\mathbf{x})\big),
\end{equation}
for $\mathbf{y}\in(\mathbb{Z}^d)^{k+1}$ and $\mathbf{x}\in(\mathbb{Z}^d)^{d+1}$. Let $H_{\mathbf{y}}:\Delta^k\times[0,1]\to\mathbb{R}^d$ be the straight-line homotopy from $F\circ\sigma_{\mathbf{y}}$ to $\sigma_{\mathbf{G}(\mathbf{y})}$, and $q$ the $(d-1)$-cochain:
\begin{equation}
    H_{\mathbf{y}}(t,s)\stackrel{\mathrm{def}}{=}(1-s)\,F\big(\sigma_{\mathbf{y}}(t)\big)+s\,\sigma_{\mathbf{G}(\mathbf{y})}(t), \qquad q(\mathbf{y})\stackrel{\mathrm{def}}{=}-\int_{\Delta^{d-1}\times[0,1]}H_{\mathbf{y}}^*\omega.
\end{equation}

The cochain $q$ is alternating. Indeed, let $\pi$ be a permutation of $\{0,\dots,d-1\}$, and let $A_\pi:\Delta^{d-1}\to\Delta^{d-1}$ be the affine map permuting the vertices of $\Delta^{d-1}$ according to $\pi$, i.e.\ $(A_\pi t)_{\pi(i)}=t_i$; its orientation is $\operatorname{sgn}(\pi)$, as one checks on transpositions. With
\begin{equation}
    \mathbf{y}_\pi\stackrel{\mathrm{def}}{=}\big(y_{\pi(0)},\dots,y_{\pi(d-1)}\big), \qquad\text{we have}\qquad \sigma_{\mathbf{y}_\pi}=\sigma_{\mathbf{y}}\circ A_\pi, \qquad \sigma_{\mathbf{G}(\mathbf{y}_\pi)}=\sigma_{\mathbf{G}(\mathbf{y})}\circ A_\pi.
\end{equation}
Hence $H_{\mathbf{y}_\pi}=H_{\mathbf{y}}\circ(A_\pi\times\mathrm{id})$, and the change of variables formula gives $q(\mathbf{y}_\pi)=\operatorname{sgn}(\pi)\,q(\mathbf{y})$.

We now prove the identity \eqref{eq:prism}. Fix $\mathbf{x}\in(\mathbb{Z}^d)^{d+1}$ and set $\mathbf{x}^{(i)}\stackrel{\mathrm{def}}{=}(x_0,\dots,\widehat{x_i},\dots,x_d)$. We have $d\omega=0$; hence $d(H_{\mathbf{x}}^*\omega)=H_{\mathbf{x}}^*(d\omega)=0$. Moreover, $H_{\mathbf{x}}$ restricts to $H_{\mathbf{x}^{(i)}}$ on $\partial_i\Delta^d\times[0,1]$, where $\partial_i\Delta^d\cong\Delta^{d-1}$ is the $i$-th face of $\Delta^d$. Since $d$ is even, the oriented boundary of $\Delta^d\times[0,1]$ is
\begin{equation}
    \partial\big(\Delta^d\times[0,1]\big) = \Delta^d\times\{1\} - \Delta^d\times\{0\} + \sum_{i=0}^d(-1)^i\,\partial_i\Delta^d\times[0,1].
\end{equation}
Therefore, Stokes' formula gives
\begin{equation}
\begin{aligned}
    0 &= \int_{\Delta^d\times[0,1]} d\big(H_{\mathbf{x}}^*\omega\big) = \int_{\partial(\Delta^d\times[0,1])} H_{\mathbf{x}}^*\omega \\
    &= \int_{\Delta^d}\sigma_{\mathbf{G}(\mathbf{x})}^*\omega - \int_{\Delta^d}(F\circ\sigma_{\mathbf{x}})^*\omega + \sum_{i=0}^d(-1)^i\int_{\Delta^{d-1}\times[0,1]}H_{\mathbf{x}^{(i)}}^*\omega \\
    &= \big(\mathbf{G}^*I[\omega]\big)(\mathbf{x}) - I[F^*\omega](\mathbf{x}) - \delta q(\mathbf{x}).
\end{aligned}
\end{equation}
This completes the proof.

\label{prop:smoothing}
The $(d-1)$-cochain $Q_U$ constructed by \Cref{lem:prism} with $F=F_U$ and $G=G_U$ is controlled. In particular,
\begin{equation}\label{eq:cU-smooth}
    c_U(P) = \tau_P\big(I[J_U\,\omega]\big).
\end{equation}

Since $\varphi_U=\mathbf{G}_U^*I[\omega]$ and $F_U^*\omega=\det(DF_U)\,\omega=J_U\,\omega$, \Cref{lem:prism} with $F=F_U$ and $G=G_U$ gives
\begin{equation}\label{eq:smoothing}
    \varphi_U = I[J_U\,\omega] + \delta Q_U.
\end{equation}
Recall from the proof of \Cref{lem:prism} that, for $\mathbf{y}\in(\mathbb{Z}^d)^d$,
\begin{equation}
    Q_U(\mathbf{y})=-\int_{\Delta^{d-1}\times[0,1]}H_{\mathbf{y}}^*\omega, \qquad H_{\mathbf{y}}(t,s)=(1-s)\,F_U\big(\sigma_{\mathbf{y}}(t)\big)+s\,\sigma_{\mathbf{G}_U(\mathbf{y})}(t).
\end{equation}

We now show that $Q_U$ is controlled. First, since $H_{\mathbf{y}}$ is Lipschitz with constant at most $C\left\langle \operatorname{diam}\mathbf{y} \right\rangle$, we have $|Q_U(\mathbf{y})|\le C\left\langle \operatorname{diam}\mathbf{y} \right\rangle^d$. Second, assume that $\mathsf{d}(\operatorname{conv}\mathbf{y},\partial U_j)\ge1$ for some $j$. The $1$-neighborhood of $\operatorname{conv}\mathbf{y}$ is connected and does not meet $\partial U_j$, so $\1_{U_j}$ is constant on it, equal to $\1_{U_j}(y_0)$. Since $\eta$ is supported in $B(0,1)$, it follows that $f_j=\1_{U_j}(y_0)$ on $\operatorname{conv}\mathbf{y}$; see \Cref{fig:smoothing}. Since moreover $(G_U)_j(y_i)=\1_{U_j}(y_i)=\1_{U_j}(y_0)$ and the $t_i$ sum to one, the $j$-th component of $H_{\mathbf{y}}$ is constant:
\begin{equation}
    (H_{\mathbf{y}})_j(t,s) = (1-s)\,\1_{U_j}(y_0) + s\sum_{i=0}^{d-1} t_i\,\1_{U_j}(y_0) = \1_{U_j}(y_0).
\end{equation}
Hence $H_{\mathbf{y}}^*\omega=0$ and $Q_U(\mathbf{y})=0$.

Therefore, if $Q_U(\mathbf{y})\neq0$, then for each $j$ there exist $p\in\operatorname{conv}\mathbf{y}$ and $z\in\partial U_j$ with $|p-z|<1$, so that
\begin{equation}
    \mathsf{d}(y_0,\partial U_j) \leq |y_0-p| + |p-z| \leq \operatorname{diam}\mathbf{y} + 1.
\end{equation}
Summing over $j$ gives $\Psi_U(y_0)\le 1+d(1+\operatorname{diam}\mathbf{y})$. If moreover $|y_0|\ge c^{-1}$, then transversality yields $|y_0|^c\le C\left\langle \operatorname{diam}\mathbf{y} \right\rangle$, and therefore
\begin{equation}
    |Q_U(\mathbf{y})| \le C\left\langle \operatorname{diam}\mathbf{y} \right\rangle^d \le C\left\langle \operatorname{diam}\mathbf{y} \right\rangle^{d+\tfrac{d+1}{c}}\left\langle y_0 \right\rangle^{-d-1}.
\end{equation}
This bound also holds, after increasing $C$, when $Q_U(\mathbf{y})=0$ or $|y_0|<c^{-1}$. Hence $Q_U$ is controlled.

