Finally, $I[F_U^*\omega]= I[J_U\,\omega] = \varphi_U-\delta Q_U$ is controlled, as the difference of two controlled cochains. Therefore \Cref{lem:cochain} and \Cref{lem:pairing} give
\begin{equation}
    c_U(P) = \tau_P(\varphi_U) = \tau_P\big(I[F_U^*\omega]\big)+\tau_P(\delta Q_U) = \tau_P\big(I[J_U\,\omega]\big).
\end{equation}
This completes the proof.

Let $\rho\stackrel{\mathrm{def}}{=} J_U-\mathcal{X}_U J_H$. By the remarks following \Cref{def:X}, $\rho\in C_0^\infty(\mathbb{R}^d)$, and $\int_{\mathbb{R}^d}\rho = 0$ because $\mathcal{X}_H=1$. By the Poincar\'e lemma for compact supports \cite[Cor.~4.7.1, p.~39]{BT82}, there exists a compactly supported $(d-1)$-form $\beta$ such that
\begin{equation}
    \rho\,\omega = d\beta.
\end{equation}
Stokes' formula gives $I[\rho\,\omega] = I[d\beta] = \delta I[\beta]$. By an argument similar to that presented in the proof of \Cref{lem:prism}, the $(d-1)$-cochain $I[\beta]$ is alternating. Because the range $\operatorname{conv}\mathbf{x}$ of a $(d-1)$-dimensional simplex $[\mathbf{x}]$ has area controlled by $\operatorname{diam} \mathbf{x}$, and $\beta$ is smooth and compactly supported,
\begin{equation}
    |I[\beta](\mathbf{x})| \le  C\left\langle \operatorname{diam}\mathbf{x} \right\rangle^{d-1}.
\end{equation}

Let $R$ be such that $\operatorname{supp}\beta \subset B(0,R)$. If $I[\beta](\mathbf{x})\neq0$, then $\operatorname{conv}\mathbf{x}$ meets $\operatorname{supp}\beta$: there exists $y\in\operatorname{conv}\mathbf{x}$ with $|y|\le R$. Since $|y-x_0|\le\operatorname{diam}\mathbf{x}$, we get $|x_0|\le R+\operatorname{diam}\mathbf{x}$, hence $\left\langle x_0 \right\rangle\le C\left\langle \operatorname{diam}\mathbf{x} \right\rangle$ and
\begin{equation}
    |I[\beta](\mathbf{x})| \le C\left\langle \operatorname{diam}\mathbf{x} \right\rangle^{d-1} \le C\left\langle \operatorname{diam}\mathbf{x} \right\rangle^{2d}\left\langle x_0 \right\rangle^{-d-1}.
\end{equation}
This bound holds trivially when $I[\beta](\mathbf{x})=0$. Hence $I[\beta]$ is controlled. 

Therefore, by \Cref{lem:pairing}:
\begin{equation}
   \tau_P\big(I[\rho\,\omega]\big) = \tau_P\big(\delta I[\beta]\big) = 0.
\end{equation}
On the other hand, from $\rho = J_U-\mathcal{X}_U J_H$ and \Cref{prop:smoothing}, we also have that:
\begin{equation}
    \tau_P\big(I[\rho\,\omega]\big) = \tau_P\big(I[J_U\,\omega]\big) - \mathcal{X}_U\cdot \tau_P\big(I[J_H\,\omega]\big) = c_U(P) - \mathcal{X}_U\cdot c_H(P).
\end{equation}
This completes the proof.
